import {
  AfterViewInit,
  Directive,
  ElementRef,
  HostBinding,
  Input,
  OnChanges,
  SecurityContext,
  SimpleChanges,
  booleanAttribute,
  inject,
} from '@angular/core';
import { DomSanitizer } from '@angular/platform-browser';

@Directive({
  selector: '[qTextHighlight], [q-text-highlight]',
})
export class QTextHighlightDirective implements OnChanges, AfterViewInit {
  @Input('qTextHighlight') characteresToHighlight = '';
  @Input({ transform: booleanAttribute }) caseSensitive = false;
  @Input({ transform: booleanAttribute }) exactMatch = false;
  @Input() text = '';

  @HostBinding('class') hostClass = 'q-text-highlight';

  private _elementRef = inject(ElementRef);
  private _domSanitizer = inject(DomSanitizer);

  ngAfterViewInit(): void {
    this._replaceHighlightedTextInHTML();
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { characteresToHighlight, caseSensitive, exactMatch, text, highlightClass } =
      changes || {};
    if (this._elementRef?.nativeElement) {
      if (characteresToHighlight || caseSensitive || exactMatch || text || highlightClass) {
        this._replaceHighlightedTextInHTML();
      }
    }
  }

  private _replaceHighlightedTextInHTML(): void {
    if (this.characteresToHighlight === '') {
      this._insertSanitizedHTML(this.text);
    } else {
      const highlightedText = this.exactMatch
        ? this._parseExactMatchText()
        : this._parseAnyMatchText();
      this._insertSanitizedHTML(highlightedText);
    }
  }

  private _insertSanitizedHTML(htmlContent: string): void {
    const sanitized = this._domSanitizer.sanitize(SecurityContext.HTML, htmlContent);
    (this._elementRef.nativeElement as HTMLElement).innerHTML = sanitized || '';
  }

  private _parseExactMatchText(): string {
    const regex = new RegExp(this.characteresToHighlight || '', this.caseSensitive ? 'g' : 'gi');
    return this.text.replace(regex, (match: string) => {
      return `<strong class="q-text-bold">${match}</strong>`;
    });
  }

  private _parseAnyMatchText(): string {
    const highlightedTextArray: string[] = [];
    this.text.split('').forEach((character) => {
      if (
        this.caseSensitive
          ? this.characteresToHighlight.includes(character)
          : this.characteresToHighlight.toLocaleLowerCase().includes(character.toLocaleLowerCase())
      ) {
        highlightedTextArray.push(`<strong class="q-text-bold">${character}</strong>`);
      } else {
        highlightedTextArray.push(character);
      }
    });
    return highlightedTextArray.join('');
  }
}
