import {
  AfterViewInit,
  booleanAttribute,
  Directive,
  HostBinding,
  inject,
  input,
  NgZone,
  ViewContainerRef,
} from '@angular/core';
import { QSharedResizeObserverService } from '@questrade/allspark-angular-components/core/services';
import { injectDestroy } from '@questrade/allspark-angular-components/core/utils';
import { auditTime, fromEvent, takeUntil } from 'rxjs';

enum QScrollShadowClass {
  UP = 'q-shadow-top',
  DOWN = 'q-shadow-bottom',
}

@Directive({ selector: '[qScrollShadow]' })
export class QScrollShadowDirective implements AfterViewInit {
  auditTimeMs = input(200, { alias: 'qScrollShadowAuditTimeMs' });
  enabled = input(true, { transform: booleanAttribute, alias: 'qScrollShadowEnabled' });

  @HostBinding('class') _hostClass = 'q-scroll-shadow';

  private _hostElement: HTMLElement | null = null;
  private readonly _destroy$ = injectDestroy();
  private readonly _resizeObserver = inject(QSharedResizeObserverService);
  private readonly _viewContainerRef = inject(ViewContainerRef);
  private readonly _ngZone = inject(NgZone);

  ngAfterViewInit(): void {
    this._hostElement = this._viewContainerRef.element.nativeElement as HTMLElement;

    if (!this._hostElement) return;

    this._ngZone.runOutsideAngular(() => {
      if (!this._hostElement) return;
      fromEvent(this._hostElement, 'scroll')
        .pipe(auditTime(this.auditTimeMs()), takeUntil(this._destroy$))
        .subscribe(this.setClasses.bind(this));
    });

    this._resizeObserver
      .observe(this._hostElement)
      ?.pipe(auditTime(this.auditTimeMs()), takeUntil(this._destroy$))
      .subscribe(this.setClasses.bind(this));
    this.setClasses();
  }

  private setClasses(): void {
    this._hostElement?.classList.remove(QScrollShadowClass.UP, QScrollShadowClass.DOWN);

    if (this.enabled()) {
      const scrollShadowClasses = this._calculateScrollShadowClasses().filter(Boolean);
      this._hostElement?.classList.add(...scrollShadowClasses);
    }
  }

  private _calculateScrollShadowClasses(): string[] {
    if (!this._hostElement) return [];

    const { clientHeight, scrollHeight, scrollTop } = this._hostElement;
    const canScrollUp = scrollTop > 0;
    const scrolled = Math.ceil(scrollHeight - scrollTop) === clientHeight;
    const canScrollDown = clientHeight < scrollHeight && !scrolled;

    return [canScrollUp ? QScrollShadowClass.UP : '', canScrollDown ? QScrollShadowClass.DOWN : ''];
  }
}
