import {
  Directive,
  ElementRef,
  Input,
  OnInit,
  Renderer2,
  inject,
  numberAttribute,
} from '@angular/core';

@Directive({
  selector: '[qLineClamp], [q-line-clamp]',
})
export class QLineClampDirective implements OnInit {
  @Input({ transform: numberAttribute }) lineClamp = 0;

  private _elementRef = inject(ElementRef);
  private _renderer = inject(Renderer2);
  private _defaultStyles: Partial<CSSStyleDeclaration> = {
    display: '-webkit-box',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    webkitBoxOrient: 'vertical',
    webkitLineClamp: 'none',
  };

  ngOnInit(): void {
    Object.assign(this._elementRef.nativeElement.style, this._defaultStyles);
    this._renderer.setStyle(this._elementRef.nativeElement, '-webkit-line-clamp', this.lineClamp);
  }
}
